<template><AppLayout><header class="head"><div><p>欢迎回来，{{ auth.user?.username }}</p><h1>求职工作台</h1></div><el-button type="primary" @click="createNew">新建简历</el-button></header><section class="stats"><div v-for="item in statCards" :key="item.key"><span>{{ item.label }}</span><strong>{{ stats[item.key] }}</strong><small>{{ item.hint }}</small></div></section><section class="panel"><div class="panel-title"><h2>最近简历</h2><router-link to="/resumes">查看全部</router-link></div><div v-if="loading" class="empty">正在加载...</div><div v-else-if="!resumes.length" class="empty"><b>还没有简历</b><span>创建第一份简历，开始你的求职准备。</span></div><div v-else class="recent-list"><button v-for="item in resumes.slice(0,4)" :key="item.id" @click="$router.push(`/resumes/${item.id}`)"><span class="file-icon">CV</span><span><b>{{ item.title }}</b><small>更新于 {{ formatDate(item.updated_at) }}</small></span><em>{{ item.status==='completed'?'已完成':'草稿' }}</em></button></div></section></AppLayout></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import AppLayout from'@/layouts/AppLayout.vue';import{useAuthStore}from'@/stores/auth';import{createResume,listResumes}from'@/api/resumes';import{getDashboard}from'@/api/dashboard';const auth=useAuthStore(),router=useRouter(),resumes=ref([]),loading=ref(true),stats=reactive({resumes:0,completed_resumes:0,analyses:0,chat_sessions:0,exports:0});const statCards=[{key:'resumes',label:'简历总数',hint:'持续维护'},{key:'completed_resumes',label:'完整简历',hint:'可直接投递'},{key:'analyses',label:'岗位分析',hint:'AI 匹配报告'},{key:'chat_sessions',label:'AI 对话',hint:'求职助手'},{key:'exports',label:'PDF 导出',hint:'投递记录'}];onMounted(async()=>{try{const[r,d]=await Promise.all([listResumes(),getDashboard()]);resumes.value=r.data.data.resumes;Object.assign(stats,d.data.data.stats)}catch(e){ElMessage.error(e.response?.data?.message||'加载失败')}finally{loading.value=false}});const createNew=async()=>{try{const{data}=await createResume({title:'未命名简历'});router.push(`/resumes/${data.data.resume.id}`)}catch(e){ElMessage.error(e.response?.data?.message||'创建失败')}};const formatDate=v=>new Date(v.replace(' ','T')+'Z').toLocaleDateString('zh-CN')</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.head p{color:#7b8190}.head h1{font-size:30px;font-weight:750}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin-bottom:24px}.stats div,.panel{background:#fff;border:1px solid #e9eaf0;border-radius:18px;box-shadow:0 5px 20px #252c4510}.stats div{padding:19px}.stats span,.stats small{display:block;color:#858b99}.stats strong{display:block;margin:5px 0;font-size:25px;font-weight:700}.stats small{font-size:11px}.panel{padding:24px}.panel-title{display:flex;justify-content:space-between}.panel-title h2{font-size:19px;font-weight:700}.panel-title a{color:#6d4aff;text-decoration:none}.empty{min-height:210px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#9096a5}.empty b{color:#333;font-size:17px}.recent-list{margin-top:14px}.recent-list button{width:100%;display:flex;align-items:center;gap:12px;padding:14px 8px;border:0;border-top:1px solid #eee;background:#fff;text-align:left;cursor:pointer}.file-icon{display:grid;place-items:center;width:38px;height:42px;background:#eeeaff;color:#6d4aff;border-radius:8px;font-weight:700}.recent-list button>span:nth-child(2){display:flex;flex:1;flex-direction:column}.recent-list b{font-weight:600}.recent-list small{color:#969baa}.recent-list em{font-style:normal;color:#777}@media(max-width:1050px){.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.stats{grid-template-columns:1fr 1fr}}
</style>
